<?php
require_once __DIR__.'/panel_security.php';panel_require_admin('panel:read');
require_once __DIR__.'/config.php';require_once __DIR__.'/panel_layout.php';
if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET') panel_fail(405,'method_not_allowed');
$type=(string)($_GET['type']??'movie');if(!in_array($type,['all','movie','series','live'],true))$type='movie';
$title=['all'=>'Catalogue','movie'=>'Catalogue Films','series'=>'Catalogue Séries','live'=>'Live TV'][$type];
$search=mb_substr(trim((string)($_GET['q']??'')),0,120);$provider=(string)($_GET['provider']??'');$category=(string)($_GET['category']??'');$visibility=(string)($_GET['visible']??'');
$where=["s.stream_type IN ('movie','series','live')"];$params=[];
if($type!=='all'){$where[]='s.stream_type=?';$params[]=$type;}
if($search!==''){$where[]='s.stream_name LIKE ?';$params[]='%'.$search.'%';}
foreach(['s.fournisseur_id'=>$provider,'s.category_id'=>$category] as $col=>$val)if($val!=='' && ctype_digit($val)){$where[]="$col=?";$params[]=(int)$val;}
if(in_array($visibility,['0','1'],true)){$where[]='s.visible=?';$params[]=(int)$visibility;}
$sort=(string)($_GET['sort']??'latest');$order=['latest'=>'s.stream_id DESC','title'=>'s.stream_name,s.stream_id','rating'=>'CAST(s.vod_rating AS DECIMAL(5,2)) DESC,s.stream_id DESC'][$sort]??'s.stream_id DESC';
$sql=implode(' AND ',$where);$q=$pdo->prepare("SELECT COUNT(*) FROM streams s WHERE $sql");$q->execute($params);$total=(int)$q->fetchColumn();
$page=max(1,min(max(1,(int)ceil($total/48)),(int)($_GET['page']??1)));$offset=($page-1)*48;
$q=$pdo->prepare("SELECT s.*,cs.quality,c.category_name,f.nom AS provider_name FROM streams s LEFT JOIN content_settings cs ON cs.stream_id=s.stream_id LEFT JOIN categories c ON c.category_id=s.category_id LEFT JOIN fournisseurs f ON f.id=s.fournisseur_id WHERE $sql ORDER BY $order LIMIT 48 OFFSET $offset");$q->execute($params);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
// IDs are taken from existing identifiers, never inferred from provider IDs.
if($type!=='live' && $rows)try{$ids=array_column($rows,'stream_id');$q=$pdo->prepare('SELECT stream_id,tmdb_id FROM movie_identifiers WHERE stream_id IN ('.implode(',',array_fill(0,count($ids),'?')).')');$q->execute($ids);$identifiers=$q->fetchAll(PDO::FETCH_KEY_PAIR);foreach($rows as &$row)if($row['stream_type']==='movie')$row['tmdb_id']=$identifiers[$row['stream_id']]??null;unset($row);}catch(PDOException $e){/* Optional legacy identifiers absent: use imported art. */}
$seasons=[];if($rows && $type!=='live'){$ids=array_column($rows,'stream_id');$q=$pdo->prepare('SELECT cs.series_parent,COUNT(DISTINCT cs.season_number) AS seasons,COUNT(*) AS episodes FROM content_settings cs JOIN streams e ON e.stream_id=cs.stream_id WHERE cs.series_parent IN ('.implode(',',array_fill(0,count($ids),'?')).') GROUP BY cs.series_parent');$q->execute($ids);foreach($q->fetchAll() as $r)$seasons[$r['series_parent']]=$r;}
$providers=$pdo->query('SELECT id,nom FROM fournisseurs ORDER BY nom')->fetchAll();
$q=$pdo->prepare('SELECT category_id,category_name FROM categories'.($type!=='all'?' WHERE content_type=?':'').' ORDER BY category_name LIMIT 2000');$q->execute($type!=='all'?[$type]:[]);$categories=$q->fetchAll();
$counts=$pdo->query("SELECT stream_type,COUNT(*) AS n FROM streams WHERE stream_type IN ('movie','series','live') GROUP BY stream_type")->fetchAll(PDO::FETCH_KEY_PAIR);
$liveStates=[];if($type==='live')try{$liveStates=$pdo->query("SELECT m.stream_id,m.state FROM panel_live_state m JOIN streams s ON s.stream_id=m.stream_id WHERE s.stream_type='live'")->fetchAll(PDO::FETCH_KEY_PAIR);}catch(PDOException $e){}
v2_begin($title);
if($type==='live'){$online=count(array_filter($liveStates,fn($s)=>$s==='ONLINE'));$offline=count(array_filter($liveStates,fn($s)=>$s==='OFFLINE'));$bouquets=(int)$pdo->query("SELECT COUNT(DISTINCT category_id) FROM streams WHERE stream_type='live'")->fetchColumn();gp_kpis([['Chaînes',$counts['live']??0,'tv','blue'],['Bouquets',$bouquets,'folder','gold'],['En ligne (dernier contrôle)',$online,'monitor','green'],['Hors ligne (dernier contrôle)',$offline,'monitor','red']]);}
else { $feature=gp_banner($rows);?><section class="gp-hero"><?=gp_picture($feature,'backdrop')?><div class="gp-hero-copy"><p class="gp-eyebrow">G-PANEL / COLLECTION</p><h2><?=gp_escape($title)?></h2><p><?=number_format($total,0,',',' ')?> contenus pour cette sélection. Affiches, genres et métadonnées de votre catalogue.</p><div class="hero-actions"><a class="btn btn-primary" href="import_selective.php">Importer des contenus <?=gp_icon('import')?></a><a class="btn" href="movie_duplicates.php">Regroupement VOD</a></div></div></section><?php }
?>
<div class="gp-chips"><?php foreach(['all'=>'Tout','movie'=>'Films','series'=>'Séries','live'=>'Live TV'] as $k=>$label):?><a class="<?=$type===$k?'active':''?>" href="?<?=gp_escape(http_build_query(['type'=>$k,'q'=>$search]))?>"><?=gp_escape($label)?> <span><?=(int)($k==='all'?array_sum($counts):($counts[$k]??0))?></span></a><?php endforeach?></div>
<form class="v2-form gp-catalog-toolbar" method="get"><input type="hidden" name="type" value="<?=gp_escape($type)?>"><label>Recherche<input type="search" name="q" value="<?=gp_escape($search)?>" placeholder="Titre du contenu…"></label><label>Bouquet<select name="category"><option value="">Tous les bouquets</option><?php foreach($categories as $c):?><option value="<?=(int)$c['category_id']?>" <?=$category===(string)$c['category_id']?'selected':''?>><?=gp_escape($c['category_name'])?></option><?php endforeach?></select></label><label>Source<select name="provider"><option value="">Toutes les sources</option><option value="0" <?=$provider==='0'?'selected':''?>>Personnel</option><?php foreach($providers as $f):?><option value="<?=(int)$f['id']?>" <?=$provider===(string)$f['id']?'selected':''?>><?=gp_escape($f['nom'])?></option><?php endforeach?></select></label><label>Visibilité<select name="visible"><option value="">Toutes</option><option value="1" <?=$visibility==='1'?'selected':''?>>Visible</option><option value="0" <?=$visibility==='0'?'selected':''?>>Masqué</option></select></label><label>Trier<select name="sort"><?php foreach(['latest'=>'Derniers ajouts','title'=>'Titre A–Z','rating'=>'Note'] as $k=>$label):?><option value="<?=$k?>" <?=$sort===$k?'selected':''?>><?=$label?></option><?php endforeach?></select></label><button>Filtrer</button><a href="editor.php">Gestion des bouquets</a></form>
<?php if(!$rows):?><section class="glass-panel gp-empty"><h2>Aucun contenu trouvé</h2><p>Modifiez vos filtres ou importez des contenus depuis vos sources.</p><a href="import_selective.php">Ouvrir les imports</a></section><?php elseif($type==='live'):?>
<section class="glass-panel"><div class="v2-table"><table><thead><tr><th>Chaîne</th><th>Bouquet</th><th>Source</th><th>État HTTP</th><th>Qualité</th><th>Visibilité</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=gp_picture($r,'poster','gp-channel-picture')?> <span data-gp-skip><?=gp_escape($r['stream_name'])?></span></td><td><?=gp_escape($r['category_name'])?></td><td><?=gp_escape($r['provider_name']??'Personnel')?></td><td><span class="gp-status" data-state="<?=gp_escape($liveStates[$r['stream_id']]??'UNKNOWN')?>"><?=gp_escape($liveStates[$r['stream_id']]??'UNKNOWN')?></span></td><td><?=gp_escape($r['quality']?:'Inconnue')?></td><td><?=$r['visible']?'Visible':'Masqué'?></td><td><a href="content_edit.php?id=<?=(int)$r['stream_id']?>">Modifier</a> · <a href="live_monitor.php?search=<?=rawurlencode($r['stream_name'])?>">Monitoring</a></td></tr><?php endforeach?></tbody></table></div></section>
<?php else:?><div class="gp-poster-grid"><?php foreach($rows as $r):?><article><?php gp_media_card($r); ?><div class="gp-catalog-meta"><?php if($r['stream_type']==='series' && isset($seasons[$r['stream_id']])):?><span><?=(int)$seasons[$r['stream_id']]['seasons']?> saisons · <?=(int)$seasons[$r['stream_id']]['episodes']?> épisodes</span><?php endif?><span><?=gp_escape($r['vod_genre']?:($r['stream_type']==='series'?'Série':'Film'))?></span><span><?=$r['visible']?'Visible':'Masqué'?></span><?php if(!empty($r['vod_runtime'])):?><span><?=gp_escape($r['vod_runtime'])?> min</span><?php endif?></div><p class="v2-muted gp-catalog-source"><?=gp_escape($r['category_name'])?></p></article><?php endforeach?></div><?php endif?>
<nav class="gp-pagination" aria-label="Pagination"><?php if($page>1):$args=$_GET;$args['page']=$page-1;?><a href="?<?=gp_escape(http_build_query($args))?>">Précédente</a><?php endif?><span><?=$total?> contenus · Page <?=$page?> / <?=max(1,(int)ceil($total/48))?></span><?php if($page*48<$total):$args=$_GET;$args['page']=$page+1;?><a href="?<?=gp_escape(http_build_query($args))?>">Suivante</a><?php endif?></nav>
<?php v2_end();
